export function Analytics({ candidates, jobs, onExport }: {
    candidates: Item[];
    jobs: Item[];
    onExport: () => void;
}) {
    const { t, tx, locale, setLocale } = useI18n();
    const evaluated = candidates.filter(c => c.evaluation), gaps: Record<string, number> = {}, skills: Record<string, number> = {};
    for (const c of evaluated) {
        for (const a of c.evaluation.result.assessments) {
            if (a.status !== 'Supported')
                gaps[a.name] = (gaps[a.name] || 0) + 1;
        }
        for (const f of c.evaluation.result.facts) {
            if (f.kind === 'Skill')
                skills[f.value] = (skills[f.value] || 0) + 1;
        }
    }
    const completion = candidates.length ? Math.round(evaluated.length / candidates.length * 100) : 0;
    const avg = evaluated.length ? Math.round(evaluated.reduce((n, c) => n + c.evaluation.duration, 0) / evaluated.length) : 0;
    const bars = (data: Record<string, number>, empty: string) => Object.keys(data).length ? <div className="chart-bars">{tx(Object.entries(data).sort((a, b) => b[1] - a[1]).slice(0, 10).map(([label, count]) => <div key={label}><div className="row between"><span>{tx(label)}</span><strong>{tx(count)}</strong></div><div><i style={{ width: `${count / Math.max(1, ...Object.values(data)) * 100}%` }}/></div></div>))}</div> : <div className="quiet-empty"><ChartIcon /><span>{tx(empty)}</span></div>;
    return <><PageHead eyebrow={t("A MEASURED PERSPECTIVE")} title={t("Recruitment analytics")} description={t("Understand your progress, evidence coverage, and the questions your team still needs to ask.")} actions={<Button onClick={onExport}><Download size={15}/>{tx("Export summary")}</Button>}/><div className="metrics">{tx([['Evaluation completion', `${completion}%`, `${evaluated.length} of ${candidates.length} candidates`], ['Awaiting human review', candidates.filter(c => ['Needs Review', 'Under HR Review'].includes(c.status)).length, 'A decision still needs your team'], ['Average evaluation', avg ? `${avg}s` : '—', 'Measured from completed evaluations'], ['Processing failures', jobs.reduce((n, j) => n + j.items.filter((i: Item) => i.state === 'failed').length, 0), 'Retained for manual retry']].map(([label, value, detail]) => <div className="metric" key={label}><div className="metric-label">{tx(label)}</div><strong>{tx(value)}</strong><div className="metric-detail">{tx(detail)}</div></div>))}</div><div className="dashboard-grid"><section className="panel"><div className="panel-head"><div><h3>{tx("Requirements needing clarification")}</h3><p>{tx("Missing supporting evidence across completed evaluations.")}</p></div></div>{tx(bars(gaps, 'Evaluate candidates to reveal evidence gaps.'))}</section><section className="panel"><div className="panel-head"><div><h3>{tx("Documented skills")}</h3><p>{tx("Source-verified skill statements, counted across resumes.")}</p></div></div>{tx(bars(skills, 'Verified skills will appear after analysis.'))}</section><section className="panel"><div className="panel-head"><div><h3>{tx("Human-managed pipeline")}</h3><p>{tx("The stages your team has recorded.")}</p></div></div>{tx(bars(Object.fromEntries(stages.map(s => [s, candidates.filter(c => c.status === s).length])), 'Import candidates to begin.'))}</section><section className="panel"><div className="panel-head"><div><h3>{tx("Documented points distribution")}</h3><p>{tx("Rubric coverage, never a measure of candidate potential.")}</p></div></div><div className="distribution">{tx([[0, 25], [25, 50], [50, 75], [75, 101]].map(([lo, hi], i) => { const n = evaluated.filter(c => c.score !== null && c.score >= lo && c.score < hi).length; return <div key={lo}><strong>{tx(n)}</strong><div><i style={{ height: `${n / Math.max(1, evaluated.length) * 100}%`, background: `var(--chart-${i})` }}/></div><span>{tx(lo)}{tx("\u2013")}{tx(hi === 101 ? 100 : hi - 1)}</span></div>; }))}</div></section></div></>;
}
